 19	PTE* alloc_pgdir_page()
 20	{
 21	    int i;
 22	    for(i = 0; i < PGDIR_PAGE_NUM; i++){
 23	        if(pgdir_page[i].valid == 0){
 24	            break;
 25	        }
 26	    }
 27	    assert(i != PGDIR_PAGE_NUM);
 28	    pgdir_page[i].valid = 1;
 29	    PTE *ret = (PTE*)(FREE_PGDIR_ADDR + i * PAGE_SIZE);
 30	    clear_pgdir((PTE*)pa2kva((uintptr_t)ret));
 31	    return ret;
 32	}
