 63	static void init_pcb()
 64	{
 65	    kernel_pcb[0].kernel_sp = (ptr_t)kernel_stack_0;
 66	    kernel_pcb[0].user_sp = (ptr_t)kernel_stack_0;
 67	    kernel_pcb[0].preempt_count = 0;
 68	    kernel_pcb[0].kernel_stack_base = (ptr_t)kernel_stack_0;
 69	    kernel_pcb[0].user_stack_base = (ptr_t)kernel_stack_0;
 70	    kernel_pcb[0].binsem_num = 0;
 71	    kernel_pcb[0].pid = 0;
 72	    kernel_pcb[0].type = KERNEL_PROCESS;
 73	    kernel_pcb[0].status = TASK_RUNNING;
 74	    kernel_pcb[0].priority = 0;
 75	    kernel_pcb[0].mask = 1;
 76	    kernel_pcb[0].cpu_id = 0;
 77	    kernel_pcb[0].pgdir = (PTE*)PGDIR_PA;
 78	    init_list_head(&kernel_pcb[0].wait_list);
 79	
 80	    kernel_pcb[1].kernel_sp = (ptr_t)kernel_stack_1;
 81	    kernel_pcb[1].user_sp = (ptr_t)kernel_stack_1;
 82	    kernel_pcb[1].preempt_count = 0;
 83	    kernel_pcb[1].kernel_stack_base = (ptr_t)kernel_stack_1;
 84	    kernel_pcb[1].user_stack_base = (ptr_t)kernel_stack_1;
 85	    kernel_pcb[1].binsem_num = 0;
 86	    kernel_pcb[1].pid = 0;
 87	    kernel_pcb[1].type = KERNEL_PROCESS;
 88	    kernel_pcb[1].status = TASK_RUNNING;
 89	    kernel_pcb[1].priority = 0;
 90	    kernel_pcb[1].mask = 2;
 91	    kernel_pcb[1].cpu_id = 1;
 92	    kernel_pcb[1].pgdir = (PTE*)PGDIR_PA;
 93	
 94	    /* initialize all pcb and add test_shell into ready_queue */
 95	    for(int i = 0; i < NUM_MAX_TASK; i++){
 96	        pcb[i].pid = -1;
 97	    }
 98	    
 99	    pcb[0].kernel_sp = pa2kva(alloc_user_page(1, NULL) + PAGE_SIZE);
100	    pcb[0].user_sp = USER_STACK_ADDR;
101	    pcb[0].preempt_count = 0;
102	    pcb[0].kernel_stack_base = pcb[0].kernel_sp;
103	    pcb[0].user_stack_base = pcb[0].user_sp;
104	    list_add_tail(&pcb[0].list, &ready_queue);
105	    init_list_head(&pcb[0].wait_list);
106	    pcb[0].binsem_num = 0;
107	    pcb[0].pid = 1;
