11	/*
12	 * using 2MB large page
13	 * kva = kpa + 0xffff_ffc0_0000_0000 use 2MB page
14	 * map all physical memory
15	 */
16	void map_kernel_page(PTE *pgdir)
17	{
18	    clear_pgdir(pgdir);
19	    /*
20	     * first level:
21	     * 0xffff_ffc0_5000_0000: VPN2 = 0x101
22	     * 0x0000_0000_5000_0000: VPN2 = 0x001
23	     */
24	    set_pfn(pgdir + 0x101, (PGDIR_PA + NORMAL_PAGE_SIZE) >> NORMAL_PAGE_SHIFT);
25	    set_attribute(pgdir + 0x101, _PAGE_PRESENT);
26	    set_pfn(pgdir + 0x001, (PGDIR_PA + NORMAL_PAGE_SIZE) >> NORMAL_PAGE_SHIFT);
27	    set_attribute(pgdir + 0x001, _PAGE_PRESENT);
28	    /*
29	     * last level:
30	     * 0x5000_0000: VPN1 = 0x80
31	     * 256MB = 2MB * 128
32	     */
33	    PTE *last_level_pgdir = (PTE*)(PGDIR_PA + NORMAL_PAGE_SIZE);
34	    clear_pgdir(last_level_pgdir);
35	    for(int i = 0; i < 128; i++){
36	        PTE* pgtable = last_level_pgdir + 0x80 + i;
37	        set_pfn(pgtable, (0x50000000 + LARGE_PAGE_SIZE * i ) >> NORMAL_PAGE_SHIFT);
38	        set_attribute(pgtable, _PAGE_PRESENT);
39	        set_attribute(pgtable, _PAGE_READ);
40	        set_attribute(pgtable, _PAGE_WRITE);
41	        set_attribute(pgtable, _PAGE_EXEC);
42	        set_attribute(pgtable, _PAGE_ACCESSED);
43	        set_attribute(pgtable, _PAGE_DIRTY);
44	    }
45	}
